import{_ as a,a0 as i,w as l,s as d,I as t,x as n,a1 as o,A as s,ao as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse(`{"title":"Linux有問必答：如何修復“X11 forwarding request failed on channel 0”錯誤 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有問必答：如何修復“X11 forwarding request failed on channel 0”錯誤 | LCTT (201410) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有問必答：如何修復“X11 forwarding request failed on channel 0”錯誤 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有問必答：如何修復“X11 forwarding request failed on channel 0”錯誤 | LCTT (201410) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201410/20140818 Linux FAQs with Answers--How to fix  'X11 forwarding request failed on channel 0'","title":"Linux有問必答：如何修復“X11 forwarding request failed on channel 0”錯誤","tag":"201410","desc":""},"relativePath":"201410/20140818 Linux FAQs with Answers--How to fix  'X11 forwarding request failed on channel 0'.md","filePath":"[post].md"}`),f={name:"201410/20140818 Linux FAQs with Answers--How to fix  'X11 forwarding request failed on channel 0'.md"};function p(x,e,h,m,w,g){const r=i("Link");return l(),d("div",null,[e[14]||(e[14]=t("h1",{id:"linux有問必答-如何修復-x11-forwarding-request-failed-on-channel-0-錯誤",tabindex:"-1"},[n("Linux有問必答：如何修復“X11 forwarding request failed on channel 0”錯誤 "),t("a",{class:"header-anchor",href:"#linux有問必答-如何修復-x11-forwarding-request-failed-on-channel-0-錯誤","aria-label":"Permalink to “Linux有問必答：如何修復“X11 forwarding request failed on channel 0”錯誤”"},"​")],-1)),e[15]||(e[15]=t("blockquote",null,[t("p",null,[t("strong",null,"問題"),n(': 當我嘗試使用SSH的X11轉發選項連接到遠程主機時, 我在登錄時遇到了一個 "X11 forwarding request failed on channel 0" （X11 轉發請求在通道0上失敗）的錯誤。 我為什麼會遇到這個錯誤，並且該如何修復它')])],-1)),e[16]||(e[16]=t("p",null,[t("img",{src:"https://farm6.staticflickr.com/5562/14909594691_ce7ca01b2d_z.jpg",alt:""})],-1)),t("p",null,[e[1]||(e[1]=n("首先，我們假設你已經正確啓用了",-1)),o(r,{href:"http://xmodulo.com/2012/11/how-to-enable-x11-forwarding-using-ssh.html"},{default:s(()=>[...e[0]||(e[0]=[n("SSH的X11轉發",-1)])]),_:1}),e[2]||(e[2]=n("。",-1))]),e[17]||(e[17]=u(`<p>如果你在登錄時遇到&quot;X11 forwarding request failed on channel 0&quot; （X11 轉發請求在通道0上失敗），這裏可能有不同的原因，解決的方法也不同。</p><h3 id="方案一" tabindex="-1">方案一 <a class="header-anchor" href="#方案一" aria-label="Permalink to “方案一”">​</a></h3><p>出於安全原因，OpenSSH服務默認將X11轉發請求綁定到本地迴環地址上，並且在DISPLAY環境變量中將主機名設置為“localhost”。在這樣的設定下，一些 X11客户端不能正確處理X11轉發，這會導致報告中的錯誤。要解決這個問題，在/etc/ssh/sshd配置文件中加入下面這幾行，它可以將X11轉發請求綁定到外網卡地址上。</p><pre><code>$ sudo vi /etc/ssh/sshd_config 
</code></pre><hr><pre><code>X11Forwarding yes
X11UseLocalhost no
</code></pre><p>重啓SSH使設置生效:</p><pre><code>$ sudo /etc/init.d/ssh restart (Debian 6, Ubuntu or Linux Mint)
$ sudo systemctl restart ssh.service (Debian 7, CentOS/RHEL 7, Fedora)
$ sudo service sshd restart (CentOS/RHEL 6) 
</code></pre><h3 id="方案二" tabindex="-1">方案二 <a class="header-anchor" href="#方案二" aria-label="Permalink to “方案二”">​</a></h3><p>如果遠程主機的SSH服務禁止了IPv6，那麼X11轉發失敗的錯誤也有可能發生。要解決這個情況下的錯誤。打開/etc/ssh/sshd配置文件，取消對&quot;AddressFamily all&quot; （如果有這條的話）的註釋。接着加入下面這行。這會強制SSH服務只使用IPv4而不是IPv6。（LCTT 譯註：此處恐有誤，AddressFamily 沒有 all 這個參數，而 any 代表同時支持 IPv6和 IPv4，以此處的場景而言，應該是關閉IPv6支持，只支持 IPv4，所以此處應該是“註釋掉 AddressFamily any”才對。）</p><pre><code>$ sudo vi /etc/ssh/sshd_config 
</code></pre><hr><pre><code>AddressFamily inet
</code></pre><p>再説一次，重啓SSH服務來完成設置</p><hr>`,15)),t("p",null,[e[4]||(e[4]=n("via: ",-1)),o(r,{href:"http://ask.xmodulo.com/fix-broken-x11-forwarding-ssh.html"},{default:s(()=>[...e[3]||(e[3]=[n("http://ask.xmodulo.com/fix-broken-x11-forwarding-ssh.html",-1)])]),_:1})]),t("p",null,[e[7]||(e[7]=n("譯者：",-1)),o(r,{href:"https://github.com/geekpi"},{default:s(()=>[...e[5]||(e[5]=[n("geekpi",-1)])]),_:1}),e[8]||(e[8]=n(" 校對：",-1)),o(r,{href:"https://github.com/wxy"},{default:s(()=>[...e[6]||(e[6]=[n("wxy",-1)])]),_:1})]),t("p",null,[e[11]||(e[11]=n("本文由 ",-1)),o(r,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[9]||(e[9]=[n("LCTT",-1)])]),_:1}),e[12]||(e[12]=n(" 原創翻譯，",-1)),o(r,{href:"http://linux.cn/"},{default:s(()=>[...e[10]||(e[10]=[n("Linux中國",-1)])]),_:1}),e[13]||(e[13]=n(" 榮譽推出",-1))])])}const S=a(f,[["render",p]]);export{T as __pageData,S as default};
